"""matplotlib.legend — Legend stubs."""

import sys as _sys


_legend_warned = set()

def _legend_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _legend_warned:
        _legend_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] legend.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Legend:
    __getattr__ = _legend_getattr_fallback

    codes = {'best': 0, 'upper right': 1, 'upper left': 2, 'lower left': 3,
             'lower right': 4, 'right': 5, 'center left': 6, 'center right': 7,
             'lower center': 8, 'upper center': 9, 'center': 10}

    def __init__(self, parent=None, handles=None, labels=None, **kwargs):
        self._parent = parent
        self.legendHandles = list(handles) if handles else []
        self.legend_handles = self.legendHandles  # alias for newer mpl
        self._labels = list(labels) if labels else []
        self._loc = kwargs.get('loc', 'best')
        self._title = kwargs.get('title', '')
        self._frameon = kwargs.get('frameon', True)
        self._fancybox = kwargs.get('fancybox', None)
        self._shadow = kwargs.get('shadow', False)
        self._framealpha = kwargs.get('framealpha', None)
        self._edgecolor = kwargs.get('edgecolor', None)
        self._facecolor = kwargs.get('facecolor', None)
        self._fontsize = kwargs.get('fontsize', None)
        self._numpoints = kwargs.get('numpoints', None)
        self._markerscale = kwargs.get('markerscale', None)
        self._ncols = kwargs.get('ncols', kwargs.get('ncol', 1))
        self._labelspacing = kwargs.get('labelspacing', None)
        self._handlelength = kwargs.get('handlelength', None)
        self._handletextpad = kwargs.get('handletextpad', None)
        self._borderpad = kwargs.get('borderpad', None)
        self._borderaxespad = kwargs.get('borderaxespad', None)
        self._columnspacing = kwargs.get('columnspacing', None)
        self._bbox_to_anchor = kwargs.get('bbox_to_anchor', None)
        self._visible = True
        self._zorder = kwargs.get('zorder', 5)
        self._draggable = None
        self._in_layout = True

    # Texts / handles
    def get_texts(self):
        class _LT:
            def __init__(s, t): s._t = t
            def get_text(s):    return s._t
            def set_text(s, x): s._t = str(x)
        return [_LT(l) for l in self._labels]
    def get_lines(self):         return list(self.legendHandles)
    def get_patches(self):       return []
    def get_legend_handler(self, *a, **kw): return None
    def get_legend_handles_labels(self):
        return list(self.legendHandles), list(self._labels)
    def get_default_handler_map(self): return {}
    def update_default_handler_map(self, m): pass
    # Title
    def set_title(self, title, **kw):
        self._title = str(title) if title else ''
    def get_title(self):
        class _T:
            def __init__(s, txt): s._txt = txt
            def get_text(s):    return s._txt
            def set_text(s, t): s._txt = str(t)
        return _T(self._title)
    # Frame
    def set_frame_on(self, b):   self._frameon = bool(b)
    def get_frame_on(self):      return self._frameon
    def set_frameon(self, b):    self._frameon = bool(b)
    def get_frameon(self):       return self._frameon
    def get_frame(self):         return None
    def set_facecolor(self, c):  self._facecolor = c
    def get_facecolor(self):     return self._facecolor
    def set_edgecolor(self, c):  self._edgecolor = c
    def get_edgecolor(self):     return self._edgecolor
    # Position
    def set_loc(self, loc):      self._loc = loc
    def get_loc(self):           return self._loc
    def set_bbox_to_anchor(self, bbox, transform=None):
        self._bbox_to_anchor = bbox
    def get_bbox_to_anchor(self): return self._bbox_to_anchor
    def set_alignment(self, a):  self._alignment = a
    def get_alignment(self):     return getattr(self, '_alignment', 'center')
    # State
    def set_visible(self, v):    self._visible = bool(v)
    def get_visible(self):       return self._visible
    def set_zorder(self, z):     self._zorder = z
    def get_zorder(self):        return self._zorder
    def set_in_layout(self, b):  self._in_layout = bool(b)
    def get_in_layout(self):     return self._in_layout
    # Drag
    def set_draggable(self, state=True, use_blit=False, update='loc'):
        self._draggable = state
        return self
    def get_draggable(self):     return bool(self._draggable)
    # Lifecycle
    def remove(self):            pass
    def draw(self, renderer):    pass
    def contains(self, ev):      return False, {}
    def get_window_extent(self, renderer=None): return None
    def get_tightbbox(self, renderer=None):     return None
    def get_children(self):
        return list(self.legendHandles)
    def findobj(self, match=None, include_self=True):
        return [self] if include_self else []
    def update_from(self, other):
        for attr in ('title', 'loc', 'visible', 'frameon'):
            getter = getattr(other, f'get_{attr}', None)
            setter = getattr(self, f'set_{attr}', None)
            if getter and setter:
                try: setter(getter())
                except Exception: pass

    @classmethod
    def get_default_handler_map(cls):
        return {}


# ─── Added: missing public names from upstream legend.py ───────────


class DraggableLegend:
    """Wrap a :class:`Legend` so the user can drag it to a new location
    by mouse. The shim records the requested state but doesn't actually
    bind to canvas events."""

    def __init__(self, legend, use_blit=False, update='loc'):
        self.legend = legend
        self.use_blit = use_blit
        self.update = update
        self._connected = False

    def connect(self):
        self._connected = True
        return self

    def disconnect(self):
        self._connected = False

    def finalize_offset(self):
        pass


# Connect the legend's ``draggable()`` method to actually return a
# DraggableLegend (instead of returning None) so callers that chain off
# the result get a useful object.
def _legend_draggable(self, state=None, use_blit=False, update='loc'):
    dl = DraggableLegend(self, use_blit=use_blit, update=update)
    if state is None or state:
        dl.connect()
    return dl
Legend.draggable = _legend_draggable


# ─── Real Legend helpers (do NOT redefine methods already present
#     in the class body — these are extras for the attribute surface). ─


def _legend_set_ncols(self, n):
    self._ncols = int(n)


def _legend_get_legend_handler(self, legend_handler_map, orig_handle):
    """Resolve the handler responsible for drawing a legend entry for
    ``orig_handle``. Walks the type MRO so subclasses fall back to the
    handler registered for their base class."""
    if legend_handler_map is None:
        return None
    for cls in type(orig_handle).__mro__:
        h = legend_handler_map.get(cls)
        if h is not None:
            return h
    return None


Legend.set_ncols          = _legend_set_ncols
Legend.get_legend_handler = _legend_get_legend_handler


# ``ncols`` / ``ncol`` aliases — older code uses ``ncol``, newer uses
# ``ncols``. Expose both as read/write properties on the same backing.
def _legend_ncols_get(self): return getattr(self, '_ncols', 1)
def _legend_ncols_set(self, n): self._ncols = int(n)
Legend.ncols = property(_legend_ncols_get, _legend_ncols_set)
Legend.ncol  = property(_legend_ncols_get, _legend_ncols_set)
